    correction: [{"quoi":"ننشر القوس الأوّل","math":"<span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">9</span><span class=\"den\">2</span></span>(x + <span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">3</span></span>) = <span class=\"frac\"><span class=\"num\">9</span><span class=\"den\">2</span></span> x + <span class=\"frac\"><span class=\"num\">21</span><span class=\"den\">2</span></span></span>"},{"quoi":"ما يُطرح بعد القوس","math":"نطرح <span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">2</span></span> x</span> ثمّ نطرح العدد 6"},{"quoi":"نطرح حدود x","math":"<span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">9</span><span class=\"den\">2</span></span> - <span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">2</span></span> = 3</span>"},{"quoi":"نطرح الأعداد","math":"<span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">21</span><span class=\"den\">2</span></span> - 6 = <span class=\"frac\"><span class=\"num\">9</span><span class=\"den\">2</span></span></span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">T = 3 x + <span class=\"frac\"><span class=\"num\">9</span><span class=\"den\">2</span></span></span>"}],
